import json

# Each option: (sender of brochure, builder of software)
options = {
    "A": ("salesperson", "salesperson"),
    "B": ("salesperson", "customer"),
    "C": ("customer", "salesperson"),
    "D": ("customer", "customer"),
}

# Constraints derived from the sentence:
# 1. The customer asks the salesperson, so the salesperson is the one asked to send the brochure.
#    The customer is the recipient ("send them").
# 2. In the second sentence, "the salesperson would be interested" names the salesperson
#    explicitly as a third party, so the pronoun "They" (the builder) is the customer.
def valid(sender, builder):
    return sender == "salesperson" and builder == "customer"

matches = [k for k, (s, b) in options.items() if valid(s, b)]

if len(matches) == 1:
    answer = "(%s)" % matches[0]
elif len(matches) > 1:
    answer = "(E) Ambiguous"
else:
    print("UNSUPPORTED")
    raise SystemExit

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "matching_options": matches,
        "rule_1": "the person asked (salesperson) is the sender; customer is the recipient",
        "rule_2": "the builder is not the salesperson, who is named separately as the one who would be interested",
    }
}, separators=(",", ":")))
